// Generated source-derived numeric inventory; regeneration checks every arm.
fn capture_typed(name: &str, raw: &str) -> Result<std::collections::BTreeMap<String, String>, serde_json::Error> {
    match name {
        "TriggerOrderType" => capture::<safe_cex_venue_hyperliquid::types::TriggerOrderType>(raw),
        "OrderType" => capture::<safe_cex_venue_hyperliquid::types::OrderType>(raw),
        "ClearinghouseState" => capture::<safe_cex_venue_hyperliquid::types::ClearinghouseState>(raw),
        "UserFills" => capture::<safe_cex_venue_hyperliquid::types::UserFills>(raw),
        "WsTrade" => capture::<safe_cex_venue_hyperliquid::types::WsTrade>(raw),
        "WsBook" => capture::<safe_cex_venue_hyperliquid::types::WsBook>(raw),
        "WsBbo" => capture::<safe_cex_venue_hyperliquid::types::WsBbo>(raw),
        "WsLevel" => capture::<safe_cex_venue_hyperliquid::types::WsLevel>(raw),
        "WsOrder" => capture::<safe_cex_venue_hyperliquid::types::WsOrder>(raw),
        "WsFill" => capture::<safe_cex_venue_hyperliquid::types::WsFill>(raw),
        "WsUserFunding" => capture::<safe_cex_venue_hyperliquid::types::WsUserFunding>(raw),
        "WsLiquidation" => capture::<safe_cex_venue_hyperliquid::types::WsLiquidation>(raw),
        "WsNonUserCancel" => capture::<safe_cex_venue_hyperliquid::types::WsNonUserCancel>(raw),
        "L2Book" => capture::<safe_cex_venue_hyperliquid::types::L2Book>(raw),
        "FundingHistoryEntry" => capture::<safe_cex_venue_hyperliquid::types::FundingHistoryEntry>(raw),
        "FundingHistory" => capture::<safe_cex_venue_hyperliquid::types::FundingHistory>(raw),
        "UserOpenOrder" => capture::<safe_cex_venue_hyperliquid::types::UserOpenOrder>(raw),
        "UserOpenOrders" => capture::<safe_cex_venue_hyperliquid::types::UserOpenOrders>(raw),
        "CancelOrderRequest" => capture::<safe_cex_venue_hyperliquid::types::CancelOrderRequest>(raw),
        "CancelOrderRequests" => capture::<safe_cex_venue_hyperliquid::types::CancelOrderRequests>(raw),
        "Signature" => capture::<safe_cex_venue_hyperliquid::types::Signature>(raw),
        "Candle" => capture::<safe_cex_venue_hyperliquid::types::Candle>(raw),
        "HyperliquidCandle" => capture::<safe_cex_venue_hyperliquid::types::HyperliquidCandle>(raw),
        "WsUserFill" => capture::<safe_cex_venue_hyperliquid::types::WsUserFill>(raw),
        "WsUserFills" => capture::<safe_cex_venue_hyperliquid::types::WsUserFills>(raw),
        "WsUserFundings" => capture::<safe_cex_venue_hyperliquid::types::WsUserFundings>(raw),
        "WsUserNonFundingLedgerUpdate" => capture::<safe_cex_venue_hyperliquid::types::WsUserNonFundingLedgerUpdate>(raw),
        "WsUserNonFundingLedgerUpdates" => capture::<safe_cex_venue_hyperliquid::types::WsUserNonFundingLedgerUpdates>(raw),
        "BuilderInfo" => capture::<safe_cex_venue_hyperliquid::types::BuilderInfo>(raw),
        _ => panic!("unrecognized source numeric type {name}"),
    }
}
